import Foundation

/// A named folder of the sidecar that groups Conversations (Hermes sessions) and the git Repositories they
/// relate to. Projects only organise: Hermes knows nothing about them. A Conversation belongs to at most one
/// Project. Unknown fields are ignored.
public struct Project: Sendable, Equatable, Identifiable, Decodable {
    /// Generated by the sidecar (a UUID).
    public let id: String
    /// Unique ignoring case.
    public let name: String
    /// Read-only in the app for now. Sorted by name by the sidecar.
    public let repositories: [ProjectRepository]
    /// Ids of the Hermes sessions in this project, in no guaranteed order.
    public let conversationIDs: [String]

    public init(id: String, name: String, repositories: [ProjectRepository] = [], conversationIDs: [String] = []) {
        self.id = id
        self.name = name
        self.repositories = repositories
        self.conversationIDs = conversationIDs
    }

    private enum CodingKeys: String, CodingKey {
        case id, name, repositories
        case conversationIDs = "conversation_ids"
    }

    public init(from decoder: any Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        id = try container.decode(String.self, forKey: .id)
        name = try container.decode(String.self, forKey: .name)
        repositories = try container.decodeIfPresent([ProjectRepository].self, forKey: .repositories) ?? []
        conversationIDs = try container.decodeIfPresent([String].self, forKey: .conversationIDs) ?? []
    }

    /// The same project with other conversations.
    public func with(conversationIDs: [String]) -> Project {
        Project(id: id, name: name, repositories: repositories, conversationIDs: conversationIDs)
    }

    /// The same project with another name.
    public func with(name: String) -> Project {
        Project(id: id, name: name, repositories: repositories, conversationIDs: conversationIDs)
    }
}

/// A git repository attached to a project.
public struct ProjectRepository: Sendable, Equatable, Identifiable, Decodable {
    /// Generated by the sidecar.
    public let id: String
    /// The path after the host, for example `owner/name`.
    public let name: String
    /// The normalised remote URL, for example `https://github.com/owner/name`.
    public let url: String

    public init(id: String, name: String, url: String) {
        self.id = id
        self.name = name
        self.url = url
    }
}

/// Why a project request failed. The sidecar answers `{"error": {"code", "message"}}`; the codes the app
/// handles get their own case, every other failure is a `HermesAPIError`.
public enum ProjectError: Error, Sendable, Equatable {
    /// `409 project_name_taken`: another project has this name, ignoring case.
    case nameTaken
    /// `422 invalid_name`: blank or too long. Carries the sidecar's explanation.
    case invalidName(String)
    /// `404 project_not_found`: the project was deleted, or the id is not one.
    case projectNotFound
    /// `422 invalid_conversation_id`: the conversation id cannot be stored in a project.
    case invalidConversationID
    /// `409 repository_already_attached`: this repository is already attached.
    case repositoryAlreadyAttached
    /// `422 invalid_repository_url`: unsupported or malformed URL. Carries the sidecar's explanation.
    case invalidRepositoryURL(String)
    /// `404 repository_not_found`: the repository is not in this project, or the id is not one.
    case repositoryNotFound
    /// Any other failure: network, key, server error, unexpected response.
    case api(HermesAPIError)

    /// Maps an error response of the sidecar: its code when the app knows it, else its status.
    static func from(status: Int, body: Data) -> ProjectError {
        let code = (try? JSONDecoder().decode(ErrorBody.self, from: body))?.error
        switch (status, code?.code) {
        case (409, "project_name_taken"):
            return .nameTaken
        case (422, "invalid_name"):
            return .invalidName(code?.message ?? "")
        case (404, "project_not_found"):
            return .projectNotFound
        case (422, "invalid_conversation_id"):
            return .invalidConversationID
        case (409, "repository_already_attached"):
            return .repositoryAlreadyAttached
        case (422, "invalid_repository_url"):
            return .invalidRepositoryURL(code?.message ?? "")
        case (404, "repository_not_found"):
            return .repositoryNotFound
        default:
            return .api(HermesAPIError.from(status: status) ?? .invalidResponse)
        }
    }

    /// Maps any error thrown by a project request: a `ProjectError` stays as is, anything else becomes `.api`.
    public static func from(_ error: any Error) -> ProjectError {
        if let error = error as? ProjectError {
            return error
        }
        return .api(HermesAPIError.from(error))
    }

    private struct ErrorBody: Decodable {
        struct Detail: Decodable {
            let code: String
            let message: String?
        }

        let error: Detail
    }
}

extension ProjectError: LocalizedError {
    public var errorDescription: String? {
        switch self {
        case .nameTaken:
            "A project with this name already exists."
        case .invalidName(let reason):
            reason.isEmpty ? "This name cannot be used." : "This name cannot be used: \(reason)."
        case .projectNotFound:
            "This project no longer exists."
        case .invalidConversationID:
            "This conversation cannot be put in a project."
        case .repositoryAlreadyAttached:
            "This repository is already attached to this project."
        case .invalidRepositoryURL(let reason):
            reason.isEmpty ? "This repository URL is not supported." : "This repository URL is not supported: \(reason)."
        case .repositoryNotFound:
            "This repository is not in this project."
        case .api(.notFound):
            "The sidecar does not know projects (404). Update hermes-sidecar or check its location."
        case .api(let error):
            error.errorDescription
        }
    }
}
